#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tide_maze_physics.c"
bool p4_game_read_motion(p4_game_context_t *context, p4_game_motion_t *out) {(void)context;(void)out;return false;}
static int total_change(const tm_state *s){int n=0;for(int i=0;i<TM_CELLS;++i)if(s->wet[i])n+=abs(s->water[i]-320);return n;}
int main(void){
 printf("{\"intent_response_after_1_second\":[");
 const int forces[]={0,35,50,99,100,200};
 for(unsigned k=0;k<sizeof(forces)/sizeof(forces[0]);++k){tm_state s={0};tm_reset(&s,0);s.intent[0].x=(int16_t)forces[k];for(int j=0;j<50;++j)tm_fluid(&s);printf("%s{\"intent\":%d,\"water_change_l1\":%d}",k?",":"",forces[k],total_change(&s));}
 tm_state s={0};s.wet[0]=s.wet[1]=1;int16_t velocity=4;int steps=0;
 while(velocity&&steps<100){s.water[0]=s.water[1]=320;flux(&s,0,1,&velocity,0);++steps;}
 printf("],\"low_flow_decay_ms\":%d,\"damping_only_initial_velocity\":4,\"full_game_state_bytes\":%zu}\n",steps*TM_STEP,sizeof(tm_state));
}
